import { topic } from '@/lib/topic-utils';

export const unit3 = [
  topic({
    id: '3.1', title: 'Introduction to Open Source Intelligence (OSINT)', minutes: 11,
    summary: 'OSINT turns lawfully accessible information into a documented, evaluated intelligence product—not an excuse for intrusive investigation.',
    sections: [
      { title: 'Open source does not mean unrestricted use', body: ['OSINT begins with information accessible without unauthorized access: public registries, official notices, public posts, published datasets, and openly reachable websites. Collection still raises privacy, terms-of-service, safety, and purpose questions. A leaked password database does not become ethical or lawful to exploit merely because someone posted it publicly.', 'Intelligence is the result of defining a requirement, collecting relevant information, evaluating sources, analyzing relationships, and communicating uncertainty. A pile of screenshots is raw material. The analyst must explain why a record matters, how it was obtained, and whether an alternative explanation remains plausible.'] },
      { title: 'Source, content, and identity are different', body: ['Evaluate the source’s proximity to the event and the content’s internal consistency. A profile may accurately display a username while using a copied photograph. A domain-registration record may identify a privacy service rather than the operator. An archived page shows what a crawler captured, not necessarily what every visitor saw at that moment.', 'Keep source URLs, capture time, hashes where appropriate, and contextual screenshots. Separate the original record from annotations. Use independent corroboration rather than counting repeated copies of the same claim as separate sources. Public information can be outdated, manipulated, or intentionally planted.'] },
      { title: 'A requirement-led collection plan', body: ['Write the question, authorized scope, permitted sources, stop conditions, and retention plan. For a suspected impersonation account, the question may be whether it reused a public alias and payment identifier—not where the person’s family lives. Exclude irrelevant personal details and protect the collected material.', 'Record confidence using consistent language. “Likely associated with the same operator” is different from “legally identified as the accused”. Consider shared devices, scheduled posts, compromised accounts, and copied branding. A good OSINT product makes its reasoning visible so a reviewer can challenge it.'] },
    ],
    practice: { title: 'Scope a public-profile review', scenario: 'A fictional shop reports an account copying its name and asking customers for advance payments.', steps: ['Write one narrow identity-linkage question.', 'List public profile, official registry, and payment-reference sources.', 'Exclude private messages and family information from the initial plan.', 'Define two observations that would support a link and one that would weaken it.'], debrief: 'A precise requirement limits intrusion and improves the quality of the final assessment.' },
    quiz: ['What distinguishes intelligence from collected public posts?', ['A larger number of screenshots.', 'Evaluation, analysis, context, and a defined requirement.', 'Use of an expensive tool.', 'Removing all source references.'], 1, 'OSINT is an analytical process, not simply downloading anything visible online.'], laws: ['it-act', 'dpdp'], sources: ['privacy', 'itact', 'nist-guide'], labId: 'osint',
  }),
  topic({
    id: '3.2', title: 'OSINT Investigation Methodology', minutes: 13,
    summary: 'Use a repeatable cycle of direction, collection, processing, analysis, dissemination, and review.',
    sections: [
      { title: 'Direction and controlled collection', body: ['Translate the complaint into prioritized intelligence requirements. Identify known identifiers, time ranges, confidence levels, and gaps. Decide which public sources can answer each question and what authority would be needed for non-public records. Establish collection boundaries before curiosity expands the scope.', 'Capture the original page or record, URL, time, and relevant context. Use a controlled environment for untrusted content and avoid signing into a target account. Preserve a clean copy and record transformations. Where a platform limits automated collection, respect the applicable restrictions and choose a lawful alternative rather than bypassing controls.'] },
      { title: 'Processing and analytical discipline', body: ['Normalize names, dates, and identifiers without silently changing the source. Build an entity table for accounts, domains, organizations, and payment references. Represent a relationship as an edge with a source and confidence, not an unexplained line on a chart. Keep contradictory records instead of deleting them to make the graph look convincing.', 'Use analysis of competing hypotheses. For a shared alias, consider the same operator, imitation, shared marketing staff, or an old transferred account. Seek discriminating evidence: a distinctive payment reference, independently verified registry contact, or a verified account migration notice. Repetition across scraper sites may still originate from one unsupported claim.'] },
      { title: 'Dissemination, review, and correction', body: ['Produce a concise assessment with key judgments, supporting observations, source references, confidence, and alternatives. Mark inference explicitly. Share only with authorized recipients and remove unnecessary personal information from presentation copies. Preserve the underlying records under the retention policy.', 'Review the assessment when new evidence arrives or a source is corrected. Maintain an audit trail of changes and avoid silently rewriting history. An intelligence lead can justify further lawful collection, but it is not itself a conviction or a warrant. The handoff should state what investigators still need to establish.'] },
    ],
    practice: { title: 'One alias, two explanations', scenario: 'A public shop profile and a suspicious payment page share the alias “northstar-demo”.', steps: ['Record both sources and the exact matching string.', 'Write same-operator and imitation hypotheses.', 'Seek an independent public identifier that discriminates between them.', 'Deliver a bounded judgment with confidence and next steps.'], debrief: 'Matching text is a lead. Independent, contextual corroboration is what changes its investigative value.' },
    quiz: ['Why use analysis of competing hypotheses?', ['To make every clue look equally certain.', 'To reduce confirmation bias by testing plausible alternatives.', 'To avoid documenting sources.', 'To prove identity from a username alone.'], 1, 'Competing hypotheses help identify evidence that distinguishes explanations rather than merely supports a favorite one.'], laws: ['it-act', 'bnss'], sources: ['nist-guide', 'privacy', 'first'], labId: 'osint',
  }),
  topic({
    id: '3.3', title: 'OSINT Tools and Techniques', minutes: 14,
    summary: 'Choose tools for a question, validate their output, and keep collection safe, reproducible, and proportionate.',
    sections: [
      { title: 'Search, capture, and public records', body: ['Search operators can narrow a public query by site, phrase, or filetype, but search-engine indexes are incomplete and time-dependent. Official registries and court or government publications provide identifiable provenance. Web archives can reveal earlier content, yet a missing archive is not proof that a page never existed. Record the query, date, and relevant result rather than only saving a cropped image.', 'A capture workflow should preserve the original response or export where feasible, record the capture environment, and hash significant files. Browser screenshots provide visual context but may omit dynamic content or headers. Tools change their interfaces and access rules; document the version and settings actually used.'] },
      { title: 'Infrastructure and media techniques', body: ['WHOIS/RDAP, passive DNS, certificate transparency, and public reputation services can help connect domains and infrastructure. Each has limitations: privacy redaction, shared hosting, historical reuse, and delayed data. A certificate containing a domain name does not prove the owner’s identity or intent. Treat infrastructure relationships as leads with dates.', 'Reverse-image search can find earlier appearances of a photograph. Metadata, landmarks, and shadows may provide context, but stripped metadata is common and location clues can be staged. Do not geolocate a private residence unless it is relevant, authorized, and necessary. This course uses fictional records rather than asking learners to investigate real people.'] },
      { title: 'Tool safety and verification', body: ['Browser automation, graph tools, and collection frameworks can accelerate repetitive work but can also leak credentials, execute untrusted content, or violate collection limits. Use an isolated environment, least-privilege accounts, and approved data handling. Never paste sensitive evidence into a random online “OSINT checker” without considering its retention and onward use.', 'Validate important findings through a second method or the original source. Record tool errors, rate limits, and unavailable fields. A result labelled “verified” by a platform may mean identity verification under that platform’s process, not proof of the investigator’s allegation. Tool names are less important than a defensible, repeatable method.'] },
    ],
    practice: { title: 'Design a three-source check', scenario: 'A public profile uses a company logo and links to a domain in the fictional dataset.', steps: ['Capture the profile and the linked page with timestamps.', 'Compare the domain’s public registration information without assuming redacted fields.', 'Check whether an independent official source confirms the claimed organization.', 'Record one tool limitation and one privacy safeguard.'], debrief: 'Three copies of the same logo are weaker than one independent, relevant record. Tool output must be interpreted, not merely accumulated.' },
    quiz: ['What is a limitation of passive DNS?', ['It reveals every keystroke on a server.', 'It proves who committed an offence.', 'It can show historical associations but may be incomplete or shared infrastructure.', 'It is the same as a lawful interception order.'], 2, 'Passive DNS is contextual infrastructure intelligence, not a complete or conclusive attribution record.'], laws: ['it-act', 'dpdp'], sources: ['privacy', 'nist-guide', 'mitre'], labId: 'osint',
  }),
  topic({
    id: '3.4', title: 'Social Media Intelligence and Investigations', minutes: 13,
    summary: 'Preserve the account, content, context, and engagement without confusing online persona with verified identity.',
    sections: [
      { title: 'What a social-media record should contain', body: ['Record the platform, visible account name, stable identifier where available, post URL, capture time, time zone, and surrounding conversation. Display names and usernames can change. A screenshot of only one post may omit edits, replies, quoted content, or a link that explains the statement. Preserve a lawful export or original file when accessible.', 'Engagement counts are dynamic and can be manipulated. Save the observation time and avoid treating views as unique people or likes as agreement. Public follower lists reveal relationships but not necessarily personal acquaintance. A shared image may be a repost, parody, or evidence of impersonation.'] },
      { title: 'Account control and content interpretation', body: ['A post originating from an account does not by itself establish which human used the keyboard. Shared credentials, delegated social-media tools, session theft, and scheduled publishing are alternative explanations. Authentication logs, device records, and witness context may be needed, and non-public records require lawful process.', 'For threats or harassment, preserve the exact wording, recipient, repetition, and relevant context. Do not amplify intimate or abusive material by circulating it in class. Use redacted presentation copies while retaining the original securely. A platform’s community-rule decision and a court’s legal finding are different determinations.'] },
      { title: 'Collection ethics and provider requests', body: ['Use complainant-controlled access or genuinely public material within the authorized scope. Do not send deceptive friend requests or bypass access controls as a classroom exercise. Record why each collected item is relevant, especially where third-party comments contain personal information. Set a retention and access policy.', 'A preservation request can protect short-lived account records while legal process is arranged. A disclosure request should identify the account and relevant date range precisely. Follow the platform’s lawful-request process and applicable Indian authority. Downloading a profile does not preserve the provider’s underlying logs or deleted backend records.'] },
    ],
    practice: { title: 'Preserve a changing profile', scenario: 'A fictional account repeatedly changes its display name while posting the same payment request.', steps: ['Capture the stable identifier and each observed display name.', 'Save full context and timestamps, not just cropped text.', 'Separate account-control evidence from content evidence.', 'Draft a narrow preservation request for relevant provider records.'], debrief: 'Stable identifiers, context, and time-aware capture make later analysis more reliable than a folder of unlabelled screenshots.' },
    quiz: ['Why preserve a stable account identifier where available?', ['It conclusively identifies the human operator.', 'Display names can change, while an identifier may help link records.', 'It removes the need for context.', 'It proves every post is true.'], 1, 'An identifier helps connect changing profile records, but account control and human attribution still require evidence.'], laws: ['it-2021', 'bnss', 'bsa'], sources: ['it2026', 'cert', 'privacy', 'bsa'], labId: 'osint',
  }),
  topic({
    id: '3.5', title: 'Deep Web: Concepts and Investigation Methods', minutes: 10,
    summary: 'The deep web is content not indexed by ordinary search engines; it is not a synonym for criminal activity or the dark web.',
    sections: [
      { title: 'Understanding non-indexed content', body: ['Search engines discover and index a subset of accessible web content. Pages behind logins, dynamic database responses, private dashboards, paywalls, and pages excluded from crawlers may be part of the deep web. Ordinary email inboxes, bank portals, and internal business systems illustrate why non-indexed does not mean illicit.', 'A page’s absence from a search result can have many causes: authentication, robots exclusion, crawling limitations, recent publication, or technical errors. It does not establish deliberate concealment. “Deep web investigation” therefore begins with identifying the access mechanism and the lawful authority to use it.'] },
      { title: 'Authorized access and reliable exports', body: ['For a complainant’s own account, use supported export tools and preserve the original response, headers, and relevant metadata. For organizational systems, define the account, role, tenant, and date range. A screenshot of a dashboard may not show filters or time-zone settings that materially change interpretation.', 'Do not bypass authentication, exploit a vulnerability, or reuse leaked credentials as an OSINT shortcut. If records are relevant but inaccessible, seek consent, provider assistance, or competent legal process. Record what the export includes and excludes, especially for paginated or dynamically loaded content.'] },
      { title: 'From private records to investigative leads', body: ['Authenticated records can be highly probative because they connect activity to account sessions, roles, and business processes. Yet logs can reflect automated actions or administrator impersonation. Corroborate important events with audit trails, payment records, and independent context. Preserve the query and export settings.', 'Where a lawful investigation leads from a public page to a login-protected resource, stop at the boundary and reassess authority. The technical ability to guess an identifier is not permission to retrieve another person’s information. Explain this boundary in the report so the reader understands why collection stopped.'] },
    ],
    practice: { title: 'Export an authorized dashboard', scenario: 'A shop owner consents to export their own store’s order history for a disputed transaction.', steps: ['Confirm the owner’s control and define the transaction date range.', 'Record filters, time zone, and export format.', 'Preserve the original export and calculate its hash.', 'Identify backend records that only the provider can supply.'], debrief: 'Deep-web material can often be collected through ordinary lawful account access. The export’s scope and provenance matter more than the label.' },
    quiz: ['Which is a typical deep-web example?', ['A public news homepage indexed by search engines.', 'An authenticated bank account dashboard.', 'Every page on the Tor network.', 'A printed newspaper.'], 1, 'The deep web includes non-indexed content such as authenticated dashboards; it is broader than anonymity networks.'], laws: ['it-act', 'bnss'], sources: ['itact', 'nist-guide', 'privacy'],
  }),
  topic({
    id: '3.6', title: 'Dark Web: Structure and Investigation Techniques', minutes: 13,
    summary: 'Understand overlay networks and investigative boundaries without treating anonymity itself as evidence of an offence.',
    sections: [
      { title: 'Structure and legitimate uses', body: ['The dark web refers to services on overlay networks that require particular software or configuration, commonly including Tor onion services. These systems can support privacy, journalism, and access under restrictive conditions as well as illicit markets. Use of anonymity technology is not, by itself, proof of criminal conduct.', 'Onion services use a different addressing and routing model from ordinary public websites. Hidden-service directories, introduction points, and rendezvous circuits help conceal aspects of the connection. Investigators should understand the architecture at a conceptual level; operational deanonymization is a specialized, legally constrained activity, not a classroom scanning exercise.'] },
      { title: 'Passive collection and provenance', body: ['A safe learning workflow uses supplied fictional pages or authorized passive observations. Preserve the visible content, capture time, relevant identifiers, and acquisition limitations. Do not purchase illicit goods, download unknown executables, or interact with abuse material. If such material is encountered unexpectedly, stop and follow the organization’s legal and safety procedure.', 'Marketplace claims, vendor names, and escrow addresses can be false or reused. Cryptocurrency transactions may provide a public ledger trail, but address ownership and transaction purpose require additional evidence. A payment graph does not automatically identify a person. Preserve the complete source and distinguish observed ledger data from inferred clustering.'] },
      { title: 'Operational and legal limits', body: ['Covert account interaction, exploitation, and network investigative techniques can affect privacy, jurisdiction, and evidential reliability. They require specific authority, careful planning, and trained personnel. A general authorization to browse public information should not be stretched into permission to deploy malware or take over a service.', 'Record the technical environment and any changes it makes. Routing, clock differences, and service instability can complicate timestamps. Cross-border cooperation may be needed for infrastructure records. The report should explain how the material was obtained and why the conclusion does not depend on unsupported assumptions about anonymity or location.'] },
    ],
    practice: { title: 'Evaluate a supplied marketplace claim', scenario: 'A fictional archived page claims that a vendor operates from a particular country.', steps: ['Record the claim as page content, not verified location.', 'List alternative explanations such as copying, deception, or shared branding.', 'Identify lawful corroborating sources without contacting the vendor.', 'Write a confidence statement and operational safety limits.'], debrief: 'The safest useful analysis often begins with source evaluation. Technical reach is not the same as legal permission or reliable attribution.' },
    quiz: ['What follows from a person’s use of an anonymity network?', ['They have necessarily committed a crime.', 'Their identity is conclusively known.', 'Nothing conclusive about criminality follows without additional evidence.', 'All their communications are public.'], 2, 'Anonymity technology has lawful and unlawful uses. Conduct and statutory elements must be established separately.'], laws: ['it-act', 'bnss', 'budapest'], sources: ['budapest', 'nist-guide', 'privacy'],
  }),
  topic({
    id: '3.7', title: 'Introduction to Digital Forensics', minutes: 12,
    summary: 'Digital forensics applies systematic, reproducible examination to digital material while preserving integrity and explaining uncertainty.',
    sections: [
      { title: 'Forensic science, not tool operation', body: ['Digital forensics concerns the identification, preservation, examination, analysis, and presentation of digital information for a legal or investigative purpose. Running a recovery program is only one possible operation. The forensic quality comes from authority, method, documentation, validation, and an explanation that can be tested by another examiner.', 'Locard’s exchange principle is often used as an analogy for digital traces, but not every action leaves a recoverable artifact and not every artifact has the meaning it first appears to have. Logging may be disabled, clocks may differ, and data may be synchronized. Use scientific reasoning rather than treating a tool’s output as unquestionable truth.'] },
      { title: 'Principles and repeatability', body: ['Preserve the original where practicable, examine verified working copies, and document necessary changes. Use methods appropriate to the question and explain their limitations. Maintain continuity from source to result. A second examiner should be able to understand the important steps and reach a comparable observation, even if proprietary software prevents exact interface replication.', 'Validation asks whether a tool or method performs as claimed for the relevant task. Verification asks whether a particular acquisition or copy matches the reference. These concepts are complementary. A validated tool can be misconfigured, and a matching hash does not validate every analytical interpretation produced by the tool.'] },
      { title: 'Form and test hypotheses', body: ['Translate the investigative question into expected artifacts. If an attachment was opened, consider application records, recent-file references, browser downloads, and temporary files. If a device was connected, consider system logs and device identifiers. Seek both supporting and contrary evidence and record why artifacts may be absent.', 'Distinguish event time, recorded time, and acquisition time. State confidence and alternatives. A forensic conclusion can be useful without being absolute: “These artifacts are consistent with the file being opened under this account” may be the strongest supportable statement. Overstatement can damage both the case and the examiner’s credibility.'] },
    ],
    practice: { title: 'From question to artifact', scenario: 'You must assess whether a spreadsheet was opened before a disputed email was sent.', steps: ['Write the event and time window precisely.', 'List expected artifacts and their limitations.', 'Define a contrary observation that would weaken the hypothesis.', 'Plan analysis on a verified copy and preserve source references.'], debrief: 'A forensic method is driven by a question and testable expectations, not by opening every artifact a tool happens to display.' },
    quiz: ['What makes an examination forensic?', ['A commercial software logo.', 'A lawful, documented, reliable, and reviewable process.', 'The examiner’s confidence alone.', 'The number of recovered files.'], 1, 'Forensic quality comes from method, integrity, documentation, and accountable interpretation—not a product label.'], laws: ['bsa', 'bnss'], sources: ['cert', 'nist-guide', 'bsa'], labId: 'hash',
  }),
  topic({
    id: '3.8', title: 'Device and Computer Forensics', minutes: 15,
    summary: 'Examine storage, operating-system artifacts, applications, and memory as parts of one system rather than isolated files.',
    sections: [
      { title: 'Storage and filesystem context', body: ['A disk image can preserve partitions, filesystem metadata, allocated files, and unallocated space. NTFS, APFS, ext4, and other filesystems record different artifacts and timestamp semantics. A modified time may change because of synchronization, metadata updates, or software behavior. Record the filesystem and tool interpretation before building a timeline.', 'On Windows, registry hives, event logs, prefetch, shortcuts, jump lists, and shellbags can help reconstruct program execution, file access, and device connections. Their presence and detail depend on configuration and version. On Linux and macOS, examine the corresponding system logs, application databases, and configuration records rather than applying Windows assumptions.'] },
      { title: 'Memory and running state', body: ['RAM may contain processes, network connections, loaded modules, encryption keys, and unsaved content. Acquisition can alter the system and require trusted tools and elevated privileges. Capture only within authority and with a clear purpose. Record tool-induced changes, acquisition failures, and the system state. A memory image can contain highly sensitive material unrelated to the case.', 'Analyze process relationships, command lines, modules, and network artifacts in context. A legitimate process name can be imitated, and a signed binary can be misused. Memory findings can corroborate disk artifacts, but volatile observations are tied to the capture time and should not be presented as a complete history.'] },
      { title: 'Attribution and anti-forensics', body: ['A user-account artifact does not prove which human was present. Consider shared credentials, remote sessions, scheduled tasks, synchronization, and malware. Correlate logon events, application activity, physical access, and independent communications. Explain why the combined evidence supports or weakens the attribution hypothesis.', 'Deleted logs, timestamp manipulation, and unusual cleanup can be relevant, but ordinary privacy tools and system maintenance also produce similar-looking artifacts. Avoid treating every anomaly as deliberate anti-forensics. Preserve the original state, compare known-good behavior, and explain alternative causes.'] },
    ],
    practice: { title: 'Build a local execution timeline', scenario: 'A supplied fictional endpoint dataset contains a download, a process event, and an outbound connection.', steps: ['Normalize timestamps and record clock uncertainty.', 'Link the download to the process through a stable artifact, not just filename similarity.', 'Compare the connection time and process relationship.', 'State what the sequence does and does not establish about user intent.'], debrief: 'A timeline becomes persuasive when artifacts independently connect the same event sequence and limitations are explicit.' },
    quiz: ['Why is a user-profile path alone weak proof of attribution?', ['It contains no characters.', 'Accounts can be shared, compromised, or used by automated processes.', 'All filesystem paths are fabricated.', 'It proves physical presence in every case.'], 1, 'The profile identifies an account context; linking that context to a human requires corroboration.'], laws: ['bsa', 'bnss'], sources: ['cert', 'nist-guide', 'mitre'], labId: 'acquisition',
  }),
  topic({
    id: '3.9', title: 'Network Forensics', minutes: 15,
    summary: 'Interpret packets, flows, and logs to reconstruct communication while respecting encryption, shared infrastructure, and collection limits.',
    sections: [
      { title: 'Packets, flows, and logs', body: ['A packet capture can contain headers and payloads; a flow record summarizes communication such as addresses, ports, times, and byte counts. Firewall, proxy, DNS, and authentication logs offer different views. Full payload capture is not always available, lawful, or useful. Define the question and collect the least intrusive representation that can answer it.', 'A connection to an IP address does not identify a website conclusively when hosting is shared or content delivery networks are involved. DNS queries can be cached, prefetched, or generated by background software. TLS encryption may hide content while leaving useful metadata. Do not infer a visited page solely from a reverse-DNS name.'] },
      { title: 'Beaconing and baseline analysis', body: ['Periodic outbound connections can indicate malware command-and-control, but legitimate update checks, telemetry, and messaging applications also beacon. Examine interval regularity, jitter, destination changes, data volume, process association, and known business behavior. Compare a baseline before labeling a pattern suspicious.', 'A useful timeline distinguishes connection start, DNS lookup, authentication, and data transfer. Normalize time zones and account for clock drift. Record capture loss and sampling because missing packets can create misleading gaps. Flow summaries may support a pattern without proving the content or purpose of the communication.'] },
      { title: 'Collection integrity and attribution', body: ['Capture at a defined observation point, document topology, filters, clock source, and capture tool settings. Hash completed capture files and restrict access because traffic can contain unrelated personal data. Live capture changes storage and may affect performance; obtain approval for material operational risks.', 'NAT can map many internal devices to one public address. DHCP leases, proxy authentication, endpoint telemetry, and provider records may help distinguish them. A destination, timing pattern, or ATT&CK technique label is not proof of a named attacker. Present the observation, plausible explanations, and further lawful collection needed.'] },
    ],
    practice: { title: 'Beacon or update service?', scenario: 'A host contacts the same fictional endpoint every five minutes with similarly sized requests.', steps: ['Filter the supplied events by source and destination.', 'Calculate intervals and compare variation and byte counts.', 'Check the baseline and process context before classifying the activity.', 'Write a cautious finding and preserve the relevant source records.'], debrief: 'Regularity is a lead. A useful conclusion considers legitimate software and identifies evidence that would distinguish it from malicious behavior.' },
    quiz: ['Does regular beaconing alone prove malware?', ['Yes, all periodic traffic is malicious.', 'No; legitimate services can also generate periodic connections.', 'Yes, if the packets use HTTPS.', 'Only when the public IP is shared.'], 1, 'Beaconing requires context, baseline comparison, and corroboration before a malicious interpretation is justified.'], laws: ['it-act', 'bnss', 'bsa'], sources: ['nist-guide', 'cert', 'mitre'], labId: 'network',
  }),
  topic({
    id: '3.10', title: 'Mobile Forensics', minutes: 14,
    summary: 'Handle phones as evolving, encrypted, cloud-connected systems whose extraction labels do not guarantee completeness.',
    sections: [
      { title: 'Device state and preservation', body: ['Record model, identifiers, lock state, connectivity, battery, operating system, and visible time. Determine whether the device is unlocked, after first unlock, or fully locked, because these states can affect accessible data. Remote wipe and network synchronization are risks, but isolation can also change evidence and device behavior.', 'There is no universal airplane-mode instruction. RF isolation, power management, and supported preservation methods require a tested procedure and qualified judgment. Keep the device powered where appropriate, document actions, and avoid repeated unlock attempts. Obtain the necessary authority and consent or legal process for access.'] },
      { title: 'Extraction methods and application data', body: ['Manual review, logical export, filesystem extraction, backup-based methods, and exploit-assisted techniques differ in scope and risk. A tool’s “full” extraction label may omit app data protected by separate encryption or unsupported formats. Record the exact tool, version, method, device state, and what could not be accessed.', 'Messages may exist in application databases, cloud backups, paired devices, and provider records. Deleted-message recovery depends on database behavior, retention, encryption, and overwriting. Preserve original databases and decode timestamps carefully. Screenshots can supplement but should not replace a reliable export when one is lawfully available.'] },
      { title: 'Location, health, and attribution', body: ['Location records can originate from GPS, Wi-Fi, cellular observations, photographs, or applications. Each has different accuracy and semantics. A point on a map may represent an estimated area or a cached location, not a person’s exact movement. Health and wearable records may be synchronized and transformed by the companion app.', 'A phone in someone’s possession is not conclusive proof that they authored every message. Consider shared access, remote compromise, notifications, and scheduled actions. Corroborate important events with device logs, provider records, and independent context. Minimize exposure of unrelated intimate data during examination and disclosure.'] },
    ],
    practice: { title: 'Choose a mobile preservation plan', scenario: 'A complainant offers an unlocked phone containing a relevant chat and consents to a scoped export.', steps: ['Record device state and the consent or authority boundary.', 'Compare a supported chat export with broader extraction options.', 'Preserve the original export, identifiers, and relevant context.', 'List cloud and recipient records that may require separate requests.'], debrief: 'A narrow supported export may be sufficient and proportionate. More invasive extraction is not automatically more reliable or lawful.' },
    quiz: ['What should an examiner record about a mobile extraction?', ['Only the phone’s colour.', 'The method, tool version, device state, scope, and limitations.', 'Only whether the screen was on.', 'A guarantee that every deleted message was recovered.'], 1, 'Extraction completeness depends on the device, method, access state, and application support.'], laws: ['bsa', 'bnss', 'dpdp'], sources: ['cert', 'privacy', 'bsa'], labId: 'acquisition',
  }),
  topic({
    id: '3.11', title: 'Email Forensics', minutes: 15,
    summary: 'Read headers, authentication results, and message context together to distinguish technical observations from claims about the sender.',
    sections: [
      { title: 'Preserve the complete message', body: ['A raw message or supported mailbox export can preserve headers, MIME structure, attachments, and encoding that a screenshot omits. Record the mailbox, folder, retrieval method, account control, and export settings. Preserve attachment hashes separately and keep the original message unchanged. Do not open suspicious attachments on an ordinary workstation.', 'Headers describe a processing path, often through multiple servers. The visible From address can differ from the envelope sender in Return-Path. Received lines are generally read from top to bottom as later-to-earlier hops, but untrusted portions can be forged. Message-ID and Date fields are not guaranteed proof of origin or actual sending time.'] },
      { title: 'SPF, DKIM, and DMARC', body: ['SPF evaluates whether a sending path is authorized for the envelope domain, commonly reflected in Return-Path. DKIM uses a cryptographic signature over selected message content and headers; a valid signature shows that the signing domain signed the surviving signed material, not that the message is benign. DMARC evaluates identifier alignment with the visible From domain under its policy and results.', 'A pass does not prove that the visible sender is a trusted person. A legitimate but compromised domain can pass authentication. A fail can arise from forwarding or configuration problems, although it remains a useful warning. Inspect the actual Authentication-Results produced by a trusted receiver and understand the alignment, not just the words “pass” or “fail”.'] },
      { title: 'Fraud reconstruction and response', body: ['Compare the message’s request with known business process, prior payment instructions, and independently verified contact details. Look for changed bank details, urgency, secrecy, and unusual reply routing. These are risk indicators, not a complete legal proof of cheating. Correlate mailbox audit logs, sign-in events, payment records, and recipient actions.', 'If compromise is suspected, preserve evidence before coordinated containment, secure accounts, revoke sessions where appropriate, and notify the relevant response team. Contact the bank through an official channel for urgent transfers. A classroom header exercise does not send email, contact a server, or test a real account.'] },
    ],
    practice: { title: 'The urgent account change', scenario: 'A message displays “Supplier Finance” but uses a different From domain and a new beneficiary account.', steps: ['Read the full headers and identify From, Return-Path, and authentication results.', 'Explain what each pass or fail establishes and what it does not.', 'Verify the request using a previously known contact, not the message’s phone number.', 'Preserve the raw message and payment trail before changing the original evidence.'], debrief: 'Authentication is one layer. Payment verification and account-control evidence often decide whether the request was genuinely authorized.' },
    quiz: ['What does a valid DKIM signature establish?', ['That the email is safe and truthful.', 'That the signing domain signed material that still verifies.', 'That the CEO personally wrote the message.', 'That no account could have been compromised.'], 1, 'DKIM provides cryptographic integrity and domain-signature information, not a guarantee of benign intent or human authorship.'], laws: ['it-act', 'bns', 'bsa'], sources: ['itact', 'cert', 'bsa'], labId: 'email',
  }),
  topic({
    id: '3.12', title: 'Cloud Forensics', minutes: 15,
    summary: 'Investigate distributed services through tenant records, audit trails, snapshots, and provider cooperation rather than assuming access to a physical server.',
    sections: [
      { title: 'Service models and evidence control', body: ['In infrastructure-as-a-service, a customer may control virtual disks, snapshots, operating-system logs, and network configuration while the provider controls the physical infrastructure. Platform and software services expose different logs and exports. Identify the service model, tenant, region, account, and subscription before planning acquisition.', 'A cloud “disk” is a distributed abstraction. Snapshot and export mechanisms may be more practical and less disruptive than attempting physical access. Record the snapshot identifier, source volume, consistency settings, creation time, encryption context, and export process. A snapshot can be crash-consistent rather than application-consistent, affecting interpretation.'] },
      { title: 'Audit logs and identity events', body: ['Control-plane logs record actions such as creating a snapshot, changing a policy, or issuing a token, while application logs record service-level events. They are not interchangeable. Examine actor identity, role, session, source context, requested action, result, and resource identifier. Service accounts and assumed roles can obscure the initiating human without additional correlation.', 'Cloud clocks, event delivery delays, and regional timestamps require careful normalization. Preserve the raw API response and query parameters, including pagination and filters. An export showing no events may reflect the wrong region, time range, or log source. Check retention, ingestion delay, and whether logging was enabled before the incident.'] },
      { title: 'Provider cooperation and volatile services', body: ['Containers, serverless functions, and autoscaled instances can disappear quickly. Preserve configuration, images, logs, and relevant runtime observations where authorized. A running container may contain useful state, but rebuilding from a known image does not recreate every runtime change. Document what the snapshot or capture actually includes.', 'Ask the provider for specific records through the competent route and explain preservation urgency. A customer cannot ordinarily seize a shared physical host. Cross-border storage and provider jurisdiction affect access. Present findings with the service boundary visible: “the tenant audit log records” is more precise than an unsupported statement about the provider’s entire infrastructure.'] },
    ],
    practice: { title: 'Reconstruct a snapshot action', scenario: 'A fictional cloud audit log shows a role creating and sharing a volume snapshot.', steps: ['Identify the role, session, resource, action, region, and timestamp.', 'Correlate the role assumption with authentication records.', 'Preserve the complete paginated log response and query settings.', 'Separate the observed API action from the identity of the human operator.'], debrief: 'Cloud attribution is a chain through identities, roles, sessions, and resources. One actor field is rarely the whole answer.' },
    quiz: ['Why is a cloud snapshot not always a complete forensic acquisition?', ['It can never contain files.', 'Its consistency, scope, encryption, and service boundary may limit what it preserves.', 'Cloud providers do not use clocks.', 'It automatically includes every provider log.'], 1, 'A snapshot represents a defined resource and state; related logs, memory, and provider records may need separate preservation.'], laws: ['bnss', 'bsa', 'dpdp'], sources: ['nist-guide', 'privacy', 'budapest', 'bsa'], labId: 'acquisition',
  }),
];
