import { topic } from '@/lib/topic-utils';

export const unit2 = [
  topic({
    id: '2.1', title: 'Introduction to Cyber Crime Investigation', minutes: 10,
    summary: 'A cyber investigation is a disciplined search for reliable answers, combining legal authority, technical examination, and human context.',
    sections: [
      { title: 'Begin with a question, not a tool', body: ['An investigation starts with an allegation or incident that can be stated precisely: who experienced what harm, when, through which account or system, and with what known loss. “Hack this person” is not an investigative objective. “Determine whether the supplier mailbox was compromised and whether the changed bank instruction caused the payment” identifies testable events and evidence sources.', 'The investigator distinguishes incident response from evidential investigation. Containment stops ongoing harm; forensics supports reliable conclusions. They overlap but can conflict, for example when rebuilding a server destroys volatile traces. A risk-based decision, made by an authorized person and documented, is better than an automatic shutdown or an unrecorded live examination.'] },
      { title: 'Roles and investigative authority', body: ['The complainant supplies context and original records. The officer in charge directs the criminal investigation, a forensic examiner analyzes exhibits, service providers supply records within lawful authority, and prosecutors assess the proof required. A private security consultant does not automatically acquire police powers. An expert’s technical skill does not replace the legal basis for access.', 'In India, cyber cells, local police, and I4C-supported coordination may all be involved. The legally competent authority and jurisdiction must be identified. Specialized forensic support can be requested, but exhibit identifiers, scope, communication, and responsibility should remain clear. For urgent financial fraud, early reporting can help preserve the payment trail.'] },
      { title: 'A reproducible investigative plan', body: ['Write the initial hypotheses and alternatives. A payment may follow account compromise, a deceptive but authentic message, malware, or an internal authorization failure. For each hypothesis, list expected observations and evidence that would disprove it. Avoid confirmation bias by actively looking for the innocent explanation.', 'Maintain an action log with time, actor, authority, action, result, and effect on evidence. Use synchronized time references and preserve originals. The plan should be revisited when new evidence appears. A defensible final report explains not only what was found, but also what was not available, what changed, and why a conclusion is limited.'] },
    ],
    practice: { title: 'Frame the first five minutes', scenario: 'A finance employee reports a suspicious invoice and a transfer made ten minutes ago.', steps: ['Write a neutral one-sentence investigative question.', 'Identify urgent loss-prevention and preservation actions.', 'Assign the complainant, officer, examiner, and bank contact roles.', 'Record two hypotheses and the evidence needed to distinguish them.'], debrief: 'A focused opening prevents both delay and uncontrolled collection. Stopping further loss and preserving the original email can proceed in parallel.' },
    quiz: ['What is the best first step in a cyber investigation?', ['Run every forensic tool available.', 'Define the allegation, scope, authority, and urgent preservation needs.', 'Assume the account owner is the offender.', 'Delete suspicious files immediately.'], 1, 'A precise, authorized plan guides proportionate collection and protects the investigation from avoidable errors.'], laws: ['bnss', 'it-act'], sources: ['bnss', 'cert', 'cybercrime'], labId: 'acquisition',
  }),
  topic({
    id: '2.2', title: 'Stages of Cyber Crime Investigation Process', minutes: 14,
    summary: 'Move from complaint to report through iterative, documented stages without treating a process diagram as a substitute for judgment.',
    sections: [
      { title: 'Intake, triage, and preservation', body: ['Intake captures the complaint, identities, incident time, affected systems, financial loss, and available records. Triage prioritizes immediate danger, ongoing theft, evidence volatility, and legal deadlines. Verify contact details independently rather than calling a number supplied by a suspected scammer. Assign a case identifier and record the initial state without promising a result.', 'Preservation can begin with the complainant’s original messages, transaction records, and relevant device state. Request provider preservation through the proper channel when necessary. A preservation request does not itself disclose content. Record the exact scope and receipt time. Avoid editing original files or asking a victim to forward material repeatedly until provenance becomes unclear.'] },
      { title: 'Collection, examination, and analysis', body: ['Collection acquires identified material using a suitable, authorized method. Examination extracts and organizes relevant artifacts from a verified working copy. Analysis interprets relationships, sequences, and competing explanations. These stages are related but distinct: finding a filename is an observation; concluding that a particular person intentionally created it requires additional evidence.', 'NIST SP 800-86 describes collection, examination, analysis, and reporting. Other models use identification, preservation, acquisition, analysis, and presentation. The terminology matters less than preserving integrity, documenting decisions, and making the process reproducible. Revisit collection when analysis reveals a new relevant source, but update the authority and scope where needed.'] },
      { title: 'Reporting, review, and feedback', body: ['Reporting connects each conclusion to an exhibit, method, and limitation. A second examiner should be able to understand tool versions, settings, time normalization, and material transformations. Prosecutors and investigators may need clarification or further lawful collection. Evidence should remain available for independent examination under appropriate safeguards.', 'Close the case operationally without destroying evidence merely because a system is restored. Retention, return, and disposal require legal and organizational authority. Capture lessons: which logs were missing, which request was late, and which control would have reduced harm? An investigation should improve future prevention as well as address the present allegation.'] },
    ],
    practice: { title: 'Sequence an invoice-fraud case', scenario: 'You have a complaint, a mailbox export, a bank reference, and a suspect laptop, but no acquisition yet.', steps: ['Record intake and preserve the available originals.', 'Define authority and prioritize volatile or short-lived records.', 'Acquire and verify the laptop through a suitable method.', 'Analyze the message and payment timeline, then draft a source-linked report.'], debrief: 'The stages can overlap. The important feature is that every transition has a documented purpose and does not silently alter the evidence.' },
    quiz: ['How does examination differ from analysis?', ['Examination always proves intent; analysis does not.', 'They are identical operations.', 'Examination organizes artifacts; analysis evaluates their meaning and competing explanations.', 'Analysis occurs before any evidence is collected.'], 2, 'Extracting an artifact and explaining its investigative significance are separate intellectual steps.'], laws: ['bnss', 'bsa'], sources: ['nist-guide', 'cert', 'bnss'], labId: 'acquisition',
  }),
  topic({
    id: '2.3', title: 'Legal Framework for Cyber Crime Investigation', minutes: 15,
    summary: 'Match each investigative action to a power, its conditions, and its safeguards under the applicable procedural law.',
    sections: [
      { title: 'Complaint, production, and search', body: ['BNSS section 173 governs information relating to cognizable offences, including specified electronic communication and signature requirements. Section 174 addresses investigation of cognizable cases. Section 94 provides for summoning production of documents or things, including electronic records, subject to its terms and exclusions. These are not interchangeable with a general search authorization.', 'Section 185 governs searches by police officers under its conditions, including recording grounds and the specified audiovisual documentation of search and seizure. Section 105 adds mandatory audio-video recording for specified searches, with implementation details to be checked. Section 106 concerns attachment of property derived from criminal activity in the situations it covers. Always read the current provision rather than relying only on old CrPC practice.'] },
      { title: 'Provider records and interception are different', body: ['BNSS section 94 can support an order for necessary documents or things, including electronic records held by a person or intermediary, subject to its conditions and exclusions. Section 69 interception, monitoring, or decryption requires its own competent authorization and the 2009 Rules’ safeguards. Section 69A blocking is not a power to search every device. A request for historical records is not the same as real-time interception.', 'A subscriber record, traffic metadata, and message content can raise different privacy and statutory concerns. Minimize the request to relevant accounts and dates. Record the recipient, authority, delivery method, response, and verification. Where the provider is overseas, identify the appropriate legal assistance or other lawful route instead of assuming a domestic notice has unlimited reach.'] },
      { title: 'Rights, documentation, and exclusion of assumptions', body: ['A device search must remain within lawful scope and be conducted with proportionate safeguards. Record the place, people, device state, identifiers, seized accessories, and reasons for each action. Where a person cannot supply a password, do not assume obstruction; self-incrimination, privilege, and the exact legal power require careful analysis. Selvi does not create a blanket answer for all biometric or password demands.', 'The applicable date determines whether a CrPC or BNSS provision governs, subject to savings. The IT Act and other special laws may add requirements. A legally sound file includes the order or authority, execution record, custody record, and examination report—not merely a forensic tool’s output. An educational checklist is not a warrant or legal advice.'] },
    ],
    practice: { title: 'Build an authority register', scenario: 'An officer seeks mailbox content, subscriber details, live interception, and a laptop search.', steps: ['Create one row for each action, not one row called “cyber investigation”.', 'Locate the relevant BNSS and IT Act provisions.', 'Record the competent authority and required safeguards.', 'Flag live interception and overseas content for specialist legal review.'], debrief: 'Different data and different methods require different powers. Precision at this stage protects both the case and individual rights.' },
    quiz: ['Which BNSS provision broadly corresponds to CrPC section 91?', ['Section 94', 'Section 173', 'Section 318', 'Section 63'], 0, 'BNSS section 94 broadly succeeds the production power in CrPC section 91; its actual text and limits still matter.'], laws: ['bnss', 'crpc', 'it-act'], sources: ['bnss', 'crpc', 'itact', 'selvi', 'privacy'],
  }),
  topic({
    id: '2.4', title: 'Nature and Characteristics of Digital Evidence', minutes: 11,
    summary: 'Digital evidence is interpretable, replicable, fragile, and dependent on context. Its value comes from a defensible account of its source and meaning.',
    sections: [
      { title: 'What makes digital evidence distinctive', body: ['Digital evidence consists of information in electronic form that can support or refute a proposition. It may be a message, file, log, database row, location record, configuration, or metadata. A file is not a complete account of its creation. The surrounding system, user actions, clock settings, and later transfers all affect interpretation.', 'Digital data can be copied without removing the original, but a copy is not automatically equivalent in every technical respect. A screenshot can show visible content while omitting headers, file metadata, and surrounding messages. A forensic image can preserve unallocated sectors that ordinary file copying misses. Choose the representation that answers the question and document what it cannot show.'] },
      { title: 'Volatility, authenticity, and integrity', body: ['Volatility describes how readily evidence changes or disappears. Memory, active connections, and running processes are generally more dynamic than an offline disk image, but cloud logs can also expire quickly. The familiar “order of volatility” is a planning heuristic, not an instruction to collect everything regardless of authority or risk.', 'Integrity means the data has not changed in an unauthorized or undocumented way. Authenticity concerns whether it is what it purports to be. Reliability concerns the process that generated it. A perfectly preserved forged email remains a forgery. Hashing supports integrity after acquisition; it does not establish that the original sender was honest or that the timestamp is correct.'] },
      { title: 'Context and uncertainty', body: ['A filename, a user profile, and an IP address are contextual clues. Shared devices, remote control, clock drift, synchronization, and automated processes can disconnect an artifact from a human action. Record the source path, acquisition time, device clock offset, tool output, and relevant surrounding events.', 'Use explicit language: observed, inferred, and unverified. For example, “The export contains a message at 10:14 UTC” is an observation; “The employee sent it intentionally” is a conclusion requiring more proof. State alternative explanations and the evidence needed to test them. This discipline makes reports more persuasive, not less.'] },
    ],
    practice: { title: 'Screenshot or export?', scenario: 'A complainant supplies a cropped screenshot of a threatening chat.', steps: ['Record what the screenshot visibly establishes and its source.', 'Preserve the original file without editing it.', 'Identify the account, full conversation, device, and export options.', 'List missing context and authentication information rather than declaring the sender proven.'], debrief: 'The screenshot can be useful evidence, but a fuller lawful export may improve context and verification. Neither format alone proves identity or truth.' },
    quiz: ['What does a matching hash primarily demonstrate?', ['The content is truthful.', 'The compared data is identical to the hashed reference.', 'The sender’s identity is conclusively established.', 'The evidence is automatically admissible.'], 1, 'A hash supports integrity comparison; authenticity, attribution, relevance, and admissibility require separate analysis.'], laws: ['bsa', 'iea'], sources: ['bsa', 'cert', 'nist-guide'], labId: 'hash',
  }),
  topic({
    id: '2.5', title: 'Sources of Electronic Evidence', minutes: 12,
    summary: 'Look beyond the visible document to devices, applications, networks, cloud services, and the people who control them.',
    sections: [
      { title: 'Endpoint and removable-media artifacts', body: ['Computers can contain documents, browser history, application databases, registry hives, event logs, shortcut files, shellbags, print artifacts, and memory dumps. External drives, memory cards, and phones may contain additional copies or synchronization records. The presence of an artifact can support a timeline, but its meaning depends on the operating system and application version.', 'Record device make, model, serial number, storage identifiers, state, connected peripherals, and relevant user accounts. A phone may depend on a paired cloud account; a laptop may contain only placeholders for cloud-hosted files. Do not assume that the device in front of you is the only or original source of every displayed record.'] },
      { title: 'Network and service-provider records', body: ['Routers, firewalls, proxy servers, DNS logs, DHCP leases, authentication systems, and packet captures can connect a local device to network activity. DHCP is particularly useful when several devices share a public IP address. Provider records may include subscriber details, access logs, payment records, or content, each with different access conditions and retention periods.', 'Email headers can reveal a submission path, but received headers can be forged and internal paths may be obscured by relays. Payment records, merchant references, and account-control evidence can be more probative than an IP address alone. Ask for the provider’s interpretation of fields and time zones, and preserve the response in its original format.'] },
      { title: 'Cloud, wearable, and human sources', body: ['Cloud audit logs, object versions, administrative actions, snapshots, and account tokens can reconstruct events outside a seized device. Smart watches, vehicles, cameras, and IoT applications may hold location or activity traces. Their data can be synchronized or transformed, so identify whether the export came from the device, a phone, or a remote service.', 'Witness statements, business-process records, and consent or authorization documents explain technical traces. A bank employee may confirm that a particular reference represents a settlement, not merely a payment request. Build a source matrix with custodian, location, acquisition method, expected retention, and legal limitations. This avoids overlooking short-lived evidence.'] },
    ],
    practice: { title: 'Create a source matrix', scenario: 'A disputed purchase was made through a shared home computer and a mobile payment app.', steps: ['List endpoint, local network, provider, bank, and human sources.', 'Identify who controls each source.', 'Mark records likely to expire first.', 'Connect each source to a specific question, such as device-to-account association.'], debrief: 'A shared public IP is only one clue. Local leases, authentication events, and payment records may distinguish devices and account control.' },
    quiz: ['Why can DHCP logs be important in a shared-network investigation?', ['They prove the identity of every user.', 'They may associate an internal address with a device at a particular time.', 'They decrypt all encrypted traffic.', 'They replace the need for lawful authority.'], 1, 'DHCP records can help connect address assignments to devices, subject to clock accuracy and reliable interpretation.'], laws: ['bnss', 'bsa', 'it-act'], sources: ['cert', 'nist-guide', 'bnss'], labId: 'network',
  }),
  topic({
    id: '2.6', title: 'Collection and Preservation of Digital Evidence', minutes: 16,
    summary: 'Collect only what is authorized, preserve what matters, and make every material action explainable.',
    sections: [
      { title: 'Prepare the scene and the method', body: ['Confirm authority, scope, safety, and the evidence question before touching a device. Photograph connections and screen state where lawful and useful. Record the device clock against a trusted reference without changing it. Identify running encryption, remote wipe risks, volatile data, and business-critical services. Assign one person to maintain the scene and action log.', 'There is no universally correct “pull the plug” rule. Shutting down may lose memory and active connections; live acquisition may change the system and require trusted tools. A running enterprise server, an encrypted phone, and an offline laptop require different decisions. Document the selected method, expected changes, and the person who authorized the trade-off.'] },
      { title: 'Acquire and verify a working copy', body: ['For suitable offline storage, a validated hardware write blocker helps prevent writes to the source. A bit-for-bit image can capture allocated and unallocated sectors, unlike a normal file copy. Record source and destination identifiers, tool and version, settings, start and end times, errors, and acquired size. Some formats store metadata and compressed segments; understand what the chosen format preserves.', 'Calculate a cryptographic hash of the acquired evidence and record it. Where the format permits, distinguish the hash of the source data from the hash of an image container. Verify the working copy before examination. A source hash may be impossible to reproduce exactly after a documented live acquisition; explain that limitation instead of inventing a match.'] },
      { title: 'Package, protect, and preserve access', body: ['Use unique exhibit identifiers, tamper-evident packaging where appropriate, and controlled storage. Protect digital copies with access controls and encryption, and manage the keys separately. For phones, isolation from networks can reduce remote alteration but may affect battery and device state; follow a tested procedure and document the choice. Never place an unfamiliar device into an untested destructive mode.', 'Preservation letters to providers should identify the account, records, and relevant period without requesting unrelated data. Record acknowledgment and follow-up authority for disclosure. Keep originals sealed or access-controlled, examine working copies, and log any export. Preservation includes retaining context: headers, configuration, logs, and the documentation needed to interpret the content.'] },
    ],
    practice: { title: 'The running encrypted laptop', scenario: 'A lawfully seized laptop is logged in, disk encryption is active, and a remote-wipe capability may exist.', steps: ['Record the visible state, clock, connections, and authorization.', 'Escalate to a qualified examiner and identify volatile-data risks.', 'Compare live collection and shutdown without applying a universal rule.', 'Document every change and prepare a custody record before transfer.'], debrief: 'A proportionate, expert-supported decision is safer than a memorized shutdown command. The record must let a reviewer understand why the method was chosen.' },
    quiz: ['What is the primary purpose of a hardware write blocker?', ['To make a forensic tool run faster.', 'To prevent writes to the connected source device during suitable acquisition.', 'To prove the identity of the computer user.', 'To decrypt every disk automatically.'], 1, 'A validated write blocker helps preserve the source; it does not prove attribution or automatically solve encryption.'], laws: ['bnss', 'bsa'], sources: ['cert', 'nist-guide', 'bnss', 'bsa'], labId: 'acquisition',
  }),
  topic({
    id: '2.7', title: 'Evidence Retrieval Techniques', minutes: 12,
    summary: 'Recover information through controlled exports, backups, filesystem analysis, and carving—while recording the limits of each method.',
    sections: [
      { title: 'Logical, filesystem, and physical access', body: ['A logical export uses an application or operating-system interface and may include only records visible to that interface. A filesystem acquisition extracts files and available metadata through the device’s storage abstraction. A physical acquisition seeks a lower-level representation where supported and lawful. These methods differ in completeness and in their ability to access deleted or protected areas.', 'Choose the least destructive method that can answer the question. A supported mail export preserving headers may be more useful than an indiscriminate disk image for one conversation. A mobile “full extraction” label is product-specific and does not guarantee every app, encrypted record, or deleted message. Record the device model, OS, tool, method, and known limitations.'] },
      { title: 'Deleted data and file carving', body: ['Deleting a file often changes filesystem references before the underlying content is overwritten. Recovery may be possible from unallocated space, journal records, shadows, backups, or cloud versions. On SSDs, TRIM and garbage collection can make older recovery assumptions unreliable. Success depends on the device, filesystem, elapsed activity, encryption, and the specific deletion process.', 'File carving identifies files using headers, footers, or internal structures rather than filesystem entries. Fragmentation can defeat simple contiguous carving, and a recovered stream may lack its original filename, path, or timestamps. Do not silently assign recovered data to a user based only on its presence in unallocated space. Preserve the source location and recovery method.'] },
      { title: 'Recovery is a process, not a promise', body: ['Use verified images or controlled exports, calculate hashes, and record tool settings. Work on copies so that recovery attempts do not alter the preserved source. Compare recovered records with independent sources such as mail attachments, backups, or provider logs. A match can strengthen context but does not erase uncertainty about who created the original.', 'Document unsuccessful attempts as well as successes. “No recoverable copy was found using this method” is different from “the file never existed”. Explain whether encryption, unsupported application formats, overwriting, or retention limits prevented retrieval. This distinction is essential in an honest expert report.'] },
    ],
    practice: { title: 'Recover the missing attachment', scenario: 'A user deleted an invoice attachment, but the message remains in a webmail account.', steps: ['Preserve the message and its headers through a supported export.', 'Check attachments, trash, backups, and provider-supported versions lawfully.', 'If examining an image, record carving settings and source offsets.', 'Compare recovered content with the original message and state what cannot be recovered.'], debrief: 'A service export and a filesystem recovery answer different questions. Use the most reliable available source rather than assuming deleted means gone.' },
    quiz: ['What is a common limitation of header-and-footer file carving?', ['It always restores the original filename and owner.', 'It cannot process digital data.', 'It may struggle with fragmented files and lose filesystem context.', 'It makes all recovered content authentic.'], 2, 'Carving can recover content without the original directory entry, ownership information, or reliable timestamps.'], laws: ['bsa', 'bnss'], sources: ['cert', 'nist-guide', 'bsa'], labId: 'hash',
  }),
  topic({
    id: '2.8', title: 'Chain of Custody in Digital Investigations', minutes: 13,
    summary: 'The chain of custody is a continuous, testable account of who controlled an exhibit, what changed, and why.',
    sections: [
      { title: 'Start the record at collection', body: ['A custody record identifies the case, exhibit, description, source, collector, date and time, location, and relevant device identifiers. It should connect the physical item to its digital acquisitions and derived exports. A laptop, its disk image, and a recovered invoice may need distinct identifiers linked by a documented parent-child relationship.', 'Record each transfer with sender, recipient, purpose, time, condition, and acknowledgment. Include storage locations and access events under the organization’s procedures. For digital copies, access logs and integrity checks can supplement signed transfer records. A hash alone is not a chain of custody because it says nothing about who possessed the source.'] },
      { title: 'Explain transformations and exceptions', body: ['Compression, format conversion, decryption, carving, and export can create new files. Preserve the original acquisition and document each transformation with its tool, settings, input, output, and hash. A report should distinguish the original exhibit from a working copy and a presentation excerpt. Redaction for disclosure should create a separate controlled copy, not overwrite the evidence.', 'If a seal is opened, record the reason, person, time, and replacement seal. If a hash differs, do not conceal it: identify whether the comparison concerns a container, extracted stream, changed live source, or corrupted copy. Investigate the discrepancy before relying on the affected material. Honest documentation of a problem is more defensible than a fabricated unbroken record.'] },
      { title: 'Custody supports, but does not decide, admissibility', body: ['Courts evaluate the reliability of the evidence and the circumstances of its handling. A gap may invite challenge, but the legal consequence depends on the facts and applicable law. Avoid categorical claims that every minor documentation error automatically excludes evidence or that a hash cures every gap.', 'Prepare a custody appendix that a non-specialist can follow from seizure to courtroom. Link exhibit IDs used in the report, seizure record, laboratory receipt, and certificate. Store personal data securely and restrict unnecessary circulation. The goal is accountable continuity, not merely collecting signatures after the investigation has finished.'] },
    ],
    practice: { title: 'Trace one invoice through the lab', scenario: 'Exhibit L01 is a laptop; I01 is its image; D01 is a recovered invoice exported from I01.', steps: ['Create a parent-child exhibit map.', 'Record the acquisition and transfer to the examiner.', 'Log the export and its hash separately from the image hash.', 'Explain which file is being certified and presented.'], debrief: 'Distinct identifiers prevent the common mistake of using a laptop’s serial number as if it identified every extracted file and later copy.' },
    quiz: ['Which information belongs in a transfer entry?', ['Only the investigator’s initials.', 'Sender, recipient, time, purpose, exhibit identity, and acknowledgment.', 'Only the final court verdict.', 'A password for unrestricted public access.'], 1, 'A transfer entry must make the movement and accountability of the exhibit reconstructable.'], laws: ['bsa', 'bnss'], sources: ['cert', 'bsa', 'nist-guide'], labId: 'acquisition',
  }),
  topic({
    id: '2.9', title: 'Admissibility of Electronic Evidence', minutes: 15,
    summary: 'An electronic file can be relevant and still require a proper route to proof. Separate admissibility, authenticity, and weight.',
    sections: [
      { title: 'The route from record to document', body: ['BSA section 57 includes electronic or digital records within documentary evidence. Section 61 addresses legal recognition of electronic records. Section 62 requires proof of electronic-record contents in accordance with section 63. Section 63 treats qualifying computer or communication-device output as a document when its conditions are satisfied. These provisions work together rather than as interchangeable slogans.', 'Distinguish the original electronic record from a printout, copied file, or other output. Section 63 addresses regular use, lawful control, ordinary input or derivation, and proper operation of the relevant device or combination of devices. A network, cloud service, or multiple-device process may require facts beyond the single handset in the witness box.'] },
      { title: 'Precedent and the current certificate', body: ['Anvar held that the special electronic-record proof route in section 65B displaced the general secondary-evidence route for the output concerned. Arjun clarified the certificate position and disapproved the relaxation in Shafhi Mohammad. It also explained that production of the original device itself is a different situation from tendering a copy or output. These holdings must now be read with the BSA’s text.', 'For an output under BSA section 63, subsection (4) calls for a certificate at each instance of submission for admission, signed by the relevant person in charge and an expert, in the Schedule’s form. The Schedule includes Part A and Part B, source particulars, and hash information. Do not reuse an old one-signature section 65B template without checking the new requirements.'] },
      { title: 'Admissible does not mean conclusive', body: ['Authentication, hearsay, relevance, privilege, and the manner of collection may raise separate issues. A certified chat can still contain a false statement or be misattributed. The court evaluates the evidence in context, including corroboration and the witness’s ability to explain the process. A certificate is not a declaration that every statement in the file is true.', 'Prepare the source witness, device custodian, and expert with accurate roles. Keep the original or reliable source available where lawful, preserve the full conversation, and disclose material limitations. The certificate builder in this course is a training worksheet, not a signed legal certificate or a guarantee of admissibility.'] },
    ],
    practice: { title: 'The original-phone question', scenario: 'A party proposes to bring the original phone to court rather than only submitting a chat printout.', steps: ['Identify the precise record and the form in which it will be tendered.', 'Read BSA sections 61–63 and the Arjun clarification.', 'Separate original-device production from proof of copied output.', 'List the facts and signatures needed for the actual submission route.'], debrief: 'Do not answer “every phone needs a certificate” or “a screenshot never needs one” in the abstract. Identify the output, statutory route, and applicable precedent.' },
    quiz: ['Which distinction is most important when discussing electronic evidence?', ['File size versus screen size.', 'Admissibility versus truth and evidential weight.', 'Laptop brand versus phone brand.', 'Internet speed versus download speed.'], 1, 'A record may be admitted yet still be unreliable, false, or insufficient to prove the allegation.'], laws: ['bsa', 'iea'], sources: ['bsa', 'bsa-schedule', 'anvar', 'arjun'], labId: 'certificate',
  }),
  topic({
    id: '2.10', title: 'Section 63(4) BSA and Electronic Evidence Certification', minutes: 18,
    summary: 'Prepare a complete, truthful certificate worksheet that identifies the output, its source, the process, and the people able to explain it.',
    sections: [
      { title: 'The statutory conditions', body: ['Section 63(2) addresses regular use of the computer or communication device by a person with lawful control, regular feeding of the relevant kind of information, proper operation during the material period, and derivation of the output from that information. Where operation was interrupted or faulty, the question includes whether the fault affected the electronic record or its accuracy.', 'Section 63(3) addresses devices used singly, in a system or network, or in combination. Identify all materially relevant sources rather than describing only the final display device. For cloud-hosted records, the export workstation and the service generating the record may play different roles. The explanation must match the actual process, not a generic assertion that “the computer was working”.'] },
      { title: 'Part A and Part B', body: ['Subsection (4) requires a certificate identifying the electronic record, describing how it was produced, giving appropriate device particulars, and addressing the conditions. It is to be signed by the person in charge of the device or relevant activities and an expert, in the Schedule’s form, at each instance of submission for admission.', 'Part A is completed by the party and identifies the source, make and model, serial or other identifiers, lawful control, ordinary operation, and hash particulars. Part B is completed by the expert and addresses the source and technical particulars, including the hash and algorithm. Attach the hash report. A person must not sign an expert portion merely because a form has a blank space; the roles and knowledge need to be genuine.'] },
      { title: 'Practical preparation and review', body: ['Preserve the exact output being submitted and calculate its hash using a documented algorithm. SHA-256 is a sensible integrity choice for this course; the Schedule lists several algorithms and an appropriate other standard. Record file names, sizes, acquisition or export steps, device identifiers, time zone, tool versions, and relevant limitations. Keep the hash report consistent with the final paginated or exported output.', 'A certificate does not cure unlawful collection, false content, or an unexplained custody gap. Check who can competently sign each part and whether multiple devices or outputs require additional explanation. Obtain the current official Schedule and legal review before filing. The interactive worksheet deliberately remains marked as training material and cannot substitute for the required signatures.'] },
    ],
    practice: { title: 'Prepare the invoice certificate worksheet', scenario: 'A lawfully controlled laptop produced an exported invoice PDF and a SHA-256 report.', steps: ['Identify the exact PDF, source device, and lawful controller.', 'Complete the party’s details and ordinary-operation explanation.', 'Add the expert’s actual particulars and attach the hash report.', 'Review both parts against the official Schedule and mark the classroom copy as training only.'], debrief: 'The certificate describes a real process. Accurate particulars and competent signatories matter more than polished wording copied from an unrelated case.' },
    quiz: ['Who signs the BSA Schedule certificate?', ['Only the advocate, in every case.', 'The party and an expert in their respective parts.', 'Only the police officer who receives it.', 'No one; an unsigned hash is always sufficient.'], 1, 'The Schedule provides Part A for the party and Part B for the expert, reflecting section 63(4).'], laws: ['bsa', 'iea'], sources: ['bsa', 'bsa-schedule', 'arjun'], labId: 'certificate',
  }),
  topic({
    id: '2.11', title: 'Documentation and Reporting of Digital Evidence', minutes: 12,
    summary: 'Write a report that lets a reader trace every conclusion back to an exhibit and reproduce the important examination steps.',
    sections: [
      { title: 'Structure for the reader', body: ['Begin with the instruction, scope, examiner, dates, exhibit list, and question. Summarize findings without overstating them. Follow with the environment, methods, tools and versions, relevant settings, analysis, limitations, and conclusions. Put hashes, acquisition logs, custody records, and detailed timelines in appendices so that the main narrative remains readable.', 'Give every exhibit a stable identifier and connect it to its source. Describe what was examined, not only what was found. If a tool produced thousands of results, explain the selection criteria and whether material contrary to the hypothesis was considered. An expert report should help the court evaluate the evidence, not advertise the examiner or the software.'] },
      { title: 'Reproducibility and transformations', body: ['Record time-zone normalization, clock offsets, decoding methods, search expressions, and relevant tool defaults. A timestamp shown in local time may differ from the underlying UTC record. A converted image or redacted excerpt is a new output; preserve its relationship to the original. Explain any error messages and whether they affect the relied-on result.', 'Separate observations from interpretations in the wording. “The log contains event ID 4624 at this time” is not equivalent to “the accused personally logged in”. Explain the event’s semantics, account type, and limitations. Where a second tool corroborates a result, describe what each actually verified rather than merely listing two product names.'] },
      { title: 'Review, disclosure, and presentation', body: ['Use technical review to check calculations, exhibit references, and the logic of conclusions. A reviewer should identify unsupported leaps, inconsistent timestamps, and missing limitations. Maintain version control and preserve the underlying notes needed to explain the report. Follow applicable disclosure obligations rather than selectively presenting only supportive artifacts.', 'A clear visual timeline can help a non-technical reader, but every item should point back to a source. Avoid inflammatory labels and unnecessary personal data. If new evidence changes the conclusion, issue a transparent correction or supplement. Professional credibility depends on being willing to revise an opinion when the evidence changes.'] },
    ],
    practice: { title: 'Repair an unsupported finding', scenario: 'A draft says: “The suspect deleted the invoice at 22:10, proving fraud.” The only source is a file deletion timestamp.', steps: ['Rewrite the observation without naming an actor.', 'Check the clock, filesystem semantics, and possible automated cleanup.', 'Identify evidence needed for attribution and intent.', 'Add a source-linked timeline and explicit limitations.'], debrief: 'A careful report can be both clear and cautious. It does not turn a filesystem event into proof of a person’s state of mind.' },
    quiz: ['Which statement is suitable for an expert report without further evidence?', ['The suspect is definitely guilty.', 'The recovered file’s timestamp is 22:10 UTC; attribution requires further evidence.', 'Everyone using this software commits fraud.', 'The tool is popular, so its output needs no explanation.'], 1, 'The report should distinguish the recorded artifact from conclusions about identity, intent, and criminal liability.'], laws: ['bsa', 'bnss'], sources: ['bsa', 'cert', 'nist-guide'], labId: 'certificate',
  }),
  topic({
    id: '2.12', title: 'Challenges in Handling Electronic Evidence', minutes: 13,
    summary: 'Plan for encryption, scale, cloud dependence, cross-border control, and fragile records without sacrificing rights or accuracy.',
    sections: [
      { title: 'Technical barriers', body: ['Encryption can protect legitimate privacy while limiting access to evidence. The correct response is not to assume guilt from refusal or to try arbitrary passwords. Identify the encryption layer, device state, available backups, key custodians, and lawful options. A cloud export or previously unlocked session may be more proportionate than invasive access, but only where authorized and reliable.', 'Volume and variety create triage problems. Multiple devices can contain duplicates, synchronized records, and inconsistent clocks. Anti-forensic techniques may alter logs or timestamps. Use known-good references, independent corroboration, and explicit uncertainty. SSD behavior, proprietary apps, and unsupported formats can make a familiar tool’s output incomplete.'] },
      { title: 'Organizational and cross-border barriers', body: ['Cloud records may be controlled by a provider in another jurisdiction, stored across regions, and retained for a short period. A customer may possess only a limited audit-log export. Identify the tenant, account, service, region, custodian, and contractual access route. Send precise preservation and production requests through the competent channel, and record the provider’s response and limitations.', 'Human factors include incomplete complaints, pressure for quick attribution, lack of trained staff, and poor handoffs. Separate duties for collection, examination, and review where practical. Protect complainants and unrelated users by limiting access and redacting disclosure copies. Do not treat a victim’s private life as an unlimited investigative resource.'] },
      { title: 'Defensible decisions under uncertainty', body: ['Use a decision register for material trade-offs: risk, options, authority, chosen action, expected impact, and outcome. If evidence cannot be preserved perfectly, explain what was possible and why. A live capture may be the only practical route; a missing provider log may be irrecoverable. Honest limitations are part of the evidential record.', 'Quality assurance should include validated tools, documented methods, peer review, secure storage, and retention schedules. A laboratory cannot promise that every challenge has a technical solution. Its professional obligation is to use a suitable process, avoid overstatement, and make the resulting evidence understandable and open to appropriate scrutiny.'] },
    ],
    practice: { title: 'The expiring cloud log', scenario: 'A relevant audit log will expire soon, but the provider is overseas and the tenant administrator is unavailable.', steps: ['Identify the custodian and urgent preservation options.', 'Record the retention deadline and source time zone.', 'Choose the competent request route and minimize the requested scope.', 'Document unavailable data and avoid claiming a complete reconstruction.'], debrief: 'Early, precise preservation can matter more than a later perfect acquisition plan. Authority and honesty remain necessary when time is short.' },
    quiz: ['What is the most defensible response to an unavailable cloud record?', ['Invent a plausible timestamp.', 'State the limitation, preserve related sources, and use lawful alternatives.', 'Assume the missing record proves the allegation.', 'Access an unrelated account without authority.'], 1, 'Missing data must be disclosed. Related records and lawful preservation may help, but they do not justify unsupported conclusions.'], laws: ['bnss', 'bsa', 'dpdp'], sources: ['privacy', 'nist-guide', 'budapest', 'bnss'],
  }),
];
